local function decodeB64(str)
    if not str or str == "" then return nil end
    if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then
        local ok, res = pcall(function() return syn.crypt.base64.decode(str) end)
        if ok and res then return res end
    end
    if crypt and crypt.base64decode then
        local ok, res = pcall(function() return crypt.base64decode(str) end)
        if ok and res then return res end
    end
    if crypt and crypt.base64_decode then
        local ok, res = pcall(function() return crypt.base64_decode(str) end)
        if ok and res then return res end
    end
    if base64_decode then
        local ok, res = pcall(function() return base64_decode(str) end)
        if ok and res then return res end
    end
    local b32 = bit32 or bit
    if b32 then
        local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local b64lookup = {}
        for i = 1, 64 do b64lookup[string.sub(b64chars, i, i)] = i - 1 end
        local output = {}
        local cleanStr = string.gsub(str, "[^" .. b64chars .. "=]", "")
        local len = #cleanStr
        for i = 1, len, 4 do
            local c1 = b64lookup[string.sub(cleanStr, i, i)] or 0
            local c2 = b64lookup[string.sub(cleanStr, i + 1, i + 1)] or 0
            local c3 = b64lookup[string.sub(cleanStr, i + 2, i + 2)] or 0
            local c4 = b64lookup[string.sub(cleanStr, i + 3, i + 3)] or 0
            local b1 = b32.bor(b32.lshift(c1, 2), b32.rshift(c2, 4))
            table.insert(output, string.char(b1))
            if string.sub(cleanStr, i + 2, i + 2) ~= "=" then
                local b2 = b32.bor(b32.lshift(b32.band(c2, 15), 4), b32.rshift(c3, 2))
                table.insert(output, string.char(b2))
            end
            if string.sub(cleanStr, i + 3, i + 3) ~= "=" then
                local b3 = b32.bor(b32.lshift(b32.band(c3, 3), 6), c4)
                table.insert(output, string.char(b3))
            end
        end
        return table.concat(output)
    end
    return nil
end
local function resolveAsset(assetKey, localFileName, fallbackId)
    local cfg = AssetConfig[assetKey]
    if cfg and cfg ~= "" and string.find(cfg, "rbxasset") then
        return cfg
    end
    if type(writefile) == "function" and type(getcustomasset) == "function" then
        local folder = "pufyftyk_assets"
        if type(makefolder) == "function" and type(isfolder) == "function" then
            if not isfolder(folder) then pcall(function() makefolder(folder) end) end
        end
        local path = folder .. "/" .. localFileName
        if type(isfile) == "function" and not isfile(path) then
            local b64 = EmbeddedAssets[localFileName]
            if b64 then
                local decoded = decodeB64(b64)
                if decoded and #decoded > 0 then
                    pcall(function() writefile(path, decoded) end)
                end
            end
        end
        if type(isfile) == "function" and isfile(path) then
            local assetUri = nil
            pcall(function() assetUri = getcustomasset(path) end)
            if assetUri and assetUri ~= "" then
                return assetUri
            end
        end
    end
    if fallbackId and fallbackId ~= "" then
        return fallbackId
    end
    return ""
end

