local function fireNetwork(name, ...)
    local args = {...}
    local remote = NetworkRemotes[name]
    if remote then
        if remote:IsA("RemoteEvent") then
            remote:FireServer(unpack(args))
        elseif remote:IsA("RemoteFunction") then
            return remote:InvokeServer(unpack(args))
        end
    end
    if ClientModules["Network"] then
        pcall(function()
            if ClientModules["Network"].Fire then
                ClientModules["Network"].Fire(name, unpack(args))
            elseif ClientModules["Network"].Invoke then
                ClientModules["Network"].Invoke(name, unpack(args))
            end
        end)
    end
    return nil
end

local function getHRP()
    local char = LocalPlayer.Character
    if not char then return nil end
    return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChildWhichIsA("BasePart")
end

local function teleportSafely(targetCFrame, offset)
    local hrp = getHRP()
    if not hrp then return false end
    local finalCF = targetCFrame
    if offset then
        finalCF = targetCFrame * CFrame.new(offset.X, offset.Y, offset.Z)
    end
    hrp.CFrame = finalCF
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    return true
end

local function parseFormattedNumber(str)
    if not str or type(str) ~= "string" then return 0 end
    local cleaned = string.gsub(str, "[,%+%$%s]", "")
    local num, suffix = string.match(cleaned, "([%d%.]+)%s*([kKmMbBtT]?)")
    if not num then return 0 end
    local n = tonumber(num) or 0
    local s = string.lower(suffix or "")
    if s == "k" then return n * 1e3
    elseif s == "m" then return n * 1e6
    elseif s == "b" then return n * 1e9
    elseif s == "t" then return n * 1e12
    end
    return n
end

local function formatCompact(n)
    n = tonumber(n) or 0
    if n >= 1e12 then return string.format("%.2fT", n / 1e12)
    elseif n >= 1e9 then return string.format("%.2fB", n / 1e9)
    elseif n >= 1e6 then return string.format("%.2fM", n / 1e6)
    elseif n >= 1e3 then return string.format("%.1fK", n / 1e3)
    end
    return tostring(math.floor(n))
end

local function formatTimer(seconds)
    local s = math.max(0, math.floor(seconds))
    local mins = math.floor(s / 60)
    local secs = s % 60
    return string.format("%02d:%02d", mins, secs)
end

local function updateCurrencies()
    pcall(function()
        local gems = 0
        local acorns = 0

        if ClientModules["Save"] then
            pcall(function()
                local data = ClientModules["Save"].Get()
                if data then
                    if data.Diamonds then gems = tonumber(data.Diamonds) or gems end
                    if data.Acorns then acorns = tonumber(data.Acorns) or acorns end
                    if data.Currency then
                        if data.Currency.Diamonds then gems = tonumber(data.Currency.Diamonds) or gems end
                        if data.Currency.Acorns then acorns = tonumber(data.Currency.Acorns) or acorns end
                    end
                end
            end)
        end

        local leaderstats = LocalPlayer:FindFirstChild("leaderstats")
        if leaderstats then
            local d = leaderstats:FindFirstChild("Diamonds") or leaderstats:FindFirstChild("Gems")
            if d and d.Value then
                if gems == 0 then gems = tonumber(d.Value) or 0 end
            end
            local a = leaderstats:FindFirstChild("Acorns") or leaderstats:FindFirstChild("Event Coins")
            if a and a.Value then
                if acorns == 0 then acorns = tonumber(a.Value) or 0 end
            end
        end

        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            for _, desc in ipairs(pg:GetDescendants()) do
                if desc:IsA("TextLabel") and desc.Visible and desc.Text and desc.Text ~= "" then
                    local p = desc.Position
                    if p.X.Scale <= 0.3 then
                        local parsed = parseFormattedNumber(desc.Text)
                        if parsed > 0 then
                            local parentName = string.lower(desc.Parent and desc.Parent.Name or "")
                            local selfName = string.lower(desc.Name)
                            if string.find(parentName, "acorn") or string.find(selfName, "acorn") then
                                if parsed > acorns then acorns = parsed end
                            elseif string.find(parentName, "diamond") or string.find(selfName, "diamond") then
                                if parsed > gems then gems = parsed end
                            else
                                if parsed > 1e10 and parsed > acorns then
                                    acorns = parsed
                                elseif parsed > 1e6 and parsed < 1e10 and gems == 0 then
                                    gems = parsed
                                end
                            end
                        end
                    end
                end
            end
        end

        State.CurrentGems = gems
        State.CurrentAcorns = acorns

        if gems > 0 and State.StartGems == nil then
            State.StartGems = gems
        end
        if State.StartGems then
            State.GemsGained = math.max(0, gems - State.StartGems)
        else
            State.GemsGained = 0
        end

        if acorns > 0 and State.StartAcorns == nil then
            State.StartAcorns = acorns
        end
    end)
end

local function getBreakablesFolder()
    local things = Workspace:FindFirstChild("__THINGS")
    if things then
        return things:FindFirstChild("Breakables")
    end
    return nil
end

local function findBreakableNear(cframeTarget, maxRadius)
    local targetPos = cframeTarget.Position
    local bestObj = nil
    local bestDist = maxRadius or 35
    local bestUid = nil

    local bFolder = getBreakablesFolder()
    if bFolder then
        for _, child in ipairs(bFolder:GetChildren()) do
            local p = nil
            if child:IsA("Model") then
                p = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart")
            elseif child:IsA("BasePart") then
                p = child
            end
            if p then
                local d = (p.Position - targetPos).Magnitude
                if d <= bestDist then
                    bestDist = d
                    bestObj = child
                    bestUid = child.Name
                end
            end
        end
    end

    if not bestObj and ClientModules["BreakableCmds"] then
        pcall(function()
            local all = ClientModules["BreakableCmds"].All()
            if type(all) == "table" then
                for uid, data in pairs(all) do
                    if data and data.pos then
                        local d = (data.pos - targetPos).Magnitude
                        if d <= bestDist then
                            bestDist = d
                            bestUid = uid
                            bestObj = uid
                        end
                    end
                end
            end
        end)
    end

    return bestObj, bestUid, bestDist
end

