                        if desc:IsA("GuiButton") and desc.Visible then
                            local t = string.lower(desc.Text or "")
                            if string.find(t, "buy") or string.find(t, "purchase") then
                                if firesignal then firesignal(desc.Activated) end
                            end
                        end
                    end
                end
            end
        end
    end)
end

